// Hardware: Fisik aus seiring waktu
function hardwareLifecycle() {
  let quality = 100;
  while (quality > 0) {
    quality -= 1; // Aus secara linear
  }
  return 'Rusak total';
}

// Software: Tidak aus, tapi bisa 'membusuk' akibat perubahan
function softwareDecay() {
  let quality = 100;
  const changes = ['patch_A', 'feature_B', 'hotfix_C'];

  changes.forEach(change => {
    if (!isWellEngineered(change)) {
      quality -= 15; // Setiap perubahan buruk = penurunan kualitas
    }
  });

  return `Kualitas tersisa: ${quality}%`;
}

// Kesimpulan: RPL hadir untuk memastikan isWellEngineered() = true
